'use client';

import React, { useState, useMemo } from 'react';
import {
    ArrowLeft,
    ArrowRight,
    Mail,
    Users,
    FileText,
    Send,
    Check,
    AlertCircle,
    Info,
    ShieldCheck,
    XCircle,
    CheckCircle2,
    TriangleAlert,
} from 'lucide-react';
import { useRouter } from 'next/navigation';
import { CreateCampaignPayload, EmailTemplate } from '../types/campaign.types';
import { useContacts } from '../hooks/useContacts';
import { useTemplates } from '../hooks/useTemplates';
import { emailCampaignService } from '../services/emailCampaignService';

// ============================================================================
// STEP DEFINITIONS
// ============================================================================

const STEPS = [
    { id: 'basics', label: 'Basics', icon: Mail },
    { id: 'audience', label: 'Audience', icon: Users },
    { id: 'content', label: 'Content', icon: FileText },
    { id: 'review', label: 'Review & Comply', icon: ShieldCheck },
    { id: 'send', label: 'Send', icon: Send },
] as const;

type StepId = (typeof STEPS)[number]['id'];

// ============================================================================
// INITIAL STATE
// ============================================================================

const INITIAL_DATA: CreateCampaignPayload = {
    name: '',
    subject: '',
    previewText: '',
    senderName: '',
    replyTo: '',
    templateId: '',
    segmentId: 'all',
    storeId: undefined,
    scheduledAt: undefined,
};

// ============================================================================
// STEP COMPONENTS
// ============================================================================

interface StepProps {
    data: CreateCampaignPayload;
    onChange: (updates: Partial<CreateCampaignPayload>) => void;
    onValidate?: (isValid: boolean) => void;
}

/** Step 1: Campaign basics */
const BasicsStep: React.FC<StepProps> = ({ data, onChange }) => (
    <div className="space-y-5">
        <div>
            <label className="block text-xs font-bold text-slate-600 uppercase tracking-wider mb-2">
                Campaign Name *
            </label>
            <input
                type="text"
                value={data.name}
                onChange={(e) => onChange({ name: e.target.value })}
                placeholder="e.g. Spring Sale Announcement"
                className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition-all"
            />
        </div>
        <div>
            <label className="block text-xs font-bold text-slate-600 uppercase tracking-wider mb-2">
                Email Subject *
            </label>
            <input
                type="text"
                value={data.subject}
                onChange={(e) => onChange({ subject: e.target.value })}
                placeholder="e.g. 🔥 Don't miss our spring sale!"
                className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition-all"
            />
        </div>
        <div>
            <label className="block text-xs font-bold text-slate-600 uppercase tracking-wider mb-2">
                Preview Text
            </label>
            <input
                type="text"
                value={data.previewText}
                onChange={(e) => onChange({ previewText: e.target.value })}
                placeholder="Short text shown in inbox preview"
                className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition-all"
            />
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
            <div>
                <label className="block text-xs font-bold text-slate-600 uppercase tracking-wider mb-2">
                    Sender Name *
                </label>
                <input
                    type="text"
                    value={data.senderName}
                    onChange={(e) => onChange({ senderName: e.target.value })}
                    placeholder="e.g. Zyappy"
                    className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition-all"
                />
            </div>
            <div>
                <label className="block text-xs font-bold text-slate-600 uppercase tracking-wider mb-2">
                    Reply-To Email *
                </label>
                <input
                    type="email"
                    value={data.replyTo}
                    onChange={(e) => onChange({ replyTo: e.target.value })}
                    placeholder="e.g. hello@zyappy.com"
                    className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition-all"
                />
            </div>
        </div>
    </div>
);

/** Step 2: Audience */
const AudienceStep: React.FC<StepProps> = ({ data, onChange, onValidate }) => {
    const { data: eligibility, loading, error } = useContacts();

    React.useEffect(() => {
        if (!loading && !error && eligibility) {
            onValidate?.(eligibility.eligible > 0);
        } else if (error) {
            // Allow proceeding past audience step even on error
            // (compliance gate at Review will catch this)
            onValidate?.(true);
        }
    }, [eligibility, loading, error, onValidate]);

    return (
        <div className="space-y-6">
            <div>
                <label className="block text-xs font-bold text-slate-600 uppercase tracking-wider mb-2">
                    Audience Selection *
                </label>
                <select
                    value={data.segmentId}
                    onChange={(e) => onChange({ segmentId: e.target.value })}
                    className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:border-indigo-500 outline-none transition-all font-medium"
                >
                    <option value="all">All Contacts</option>
                </select>
            </div>

            {loading ? (
                <div className="py-10 flex flex-col items-center justify-center gap-3">
                    <div className="w-8 h-8 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin" />
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Calculating eligibility...</p>
                </div>
            ) : error ? (
                <div className="p-4 bg-red-50 border border-red-100 rounded-xl flex items-center gap-3">
                    <AlertCircle className="w-5 h-5 text-red-500" />
                    <p className="text-sm text-red-700 font-medium">Failed to calculate audience.</p>
                </div>
            ) : eligibility ? (
                <div className="space-y-6 animate-in fade-in slide-in-from-top-2 duration-500">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <div className="p-4 bg-slate-50 border border-slate-200 rounded-2xl">
                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Total</p>
                            <p className="text-2xl font-black text-slate-900">{eligibility.total.toLocaleString()}</p>
                        </div>
                        <div className="p-4 bg-emerald-50 border border-emerald-100 rounded-2xl ring-1 ring-emerald-200/50">
                            <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest mb-1">Eligible</p>
                            <p className="text-2xl font-black text-emerald-700">{eligibility.eligible.toLocaleString()}</p>
                        </div>
                        <div className="p-4 bg-rose-50 border border-rose-100 rounded-2xl ring-1 ring-rose-200/50">
                            <p className="text-[10px] font-black text-rose-500 uppercase tracking-widest mb-1">Excluded</p>
                            <p className="text-2xl font-black text-rose-700">{eligibility.excluded.toLocaleString()}</p>
                        </div>
                    </div>

                    {eligibility.excluded > 0 && (
                        <div className="space-y-3">
                            <div className="flex items-center gap-2">
                                <Info className="w-4 h-4 text-slate-400" />
                                <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest">Exclusions</h3>
                            </div>
                            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
                                {[
                                    { label: 'No Consent', count: eligibility.reasons.noConsent },
                                    { label: 'Unsubscribed', count: eligibility.reasons.unsubscribed },
                                    { label: 'Suppressed', count: eligibility.reasons.suppressed },
                                    { label: 'Invalid', count: eligibility.reasons.invalid },
                                ].map((item) => (
                                    <div key={item.label} className="px-4 py-3 bg-white border border-slate-100 rounded-xl shadow-sm flex items-center justify-between">
                                        <span className="text-xs font-bold text-slate-500">{item.label}</span>
                                        <span className="text-sm font-black text-slate-900">{item.count.toLocaleString()}</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </div>
            ) : null}
        </div>
    );
};

/** Step 3: Content */
const ContentStep: React.FC<StepProps> = ({ data, onChange, onValidate }) => {
    const { data: templates, loading, error } = useTemplates();
    const [testEmail, setTestEmail] = useState('');
    const [sendingTest, setSendingTest] = useState(false);
    const [testFeedback, setTestFeedback] = useState<{ type: 'success' | 'error'; message: string } | null>(null);

    const selectedTemplate = templates.find((t: EmailTemplate) => t.id === data.templateId);

    React.useEffect(() => {
        onValidate?.(!!data.templateId);
    }, [data.templateId, onValidate]);

    const handleSendTest = async () => {
        if (!testEmail || !data.templateId) return;
        setSendingTest(true);
        setTestFeedback(null);
        try {
            await emailCampaignService.sendTestEmail(data.templateId, testEmail);
            setTestFeedback({ type: 'success', message: 'Test email sent!' });
        } catch (err) {
            setTestFeedback({ type: 'error', message: 'Failed to send test.' });
        } finally {
            setSendingTest(false);
        }
    };

    return (
        <div className="flex flex-col lg:flex-row gap-6">
            <div className="w-full lg:w-1/3 space-y-4">
                <div className="flex items-center justify-between h-5">
                    <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest">Select Template</h3>
                </div>

                {loading ? (
                    <div className="space-y-2">
                        {[...Array(3)].map((_, i) => (
                            <div key={i} className="h-16 bg-slate-50 border border-slate-100 rounded-xl animate-pulse" />
                        ))}
                    </div>
                ) : error ? (
                    <div className="p-4 bg-red-50 text-red-600 rounded-xl text-xs font-medium">Failed to load templates.</div>
                ) : (
                    <div className="space-y-2 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                        {templates.map((template) => (
                            <button
                                key={template.id}
                                onClick={() => onChange({ templateId: template.id })}
                                className={`w-full text-left p-4 rounded-xl border transition-all duration-200
                                    ${data.templateId === template.id 
                                        ? 'bg-indigo-50 border-indigo-200 ring-1 ring-indigo-200' 
                                        : 'bg-white border-slate-200 hover:border-indigo-300'}`}
                            >
                                <div className="flex items-center justify-between mb-1">
                                    <span className={`text-sm font-bold ${data.templateId === template.id ? 'text-indigo-900' : 'text-slate-700'}`}>
                                        {template.name}
                                    </span>
                                    {data.templateId === template.id && <Check className="w-3.5 h-3.5 text-indigo-600" />}
                                </div>
                                <p className="text-[10px] text-slate-400 font-medium uppercase tracking-wider truncate">
                                    {template.subject || 'No subject'}
                                </p>
                            </button>
                        ))}
                    </div>
                )}
            </div>

            <div className="flex-1 space-y-5">
                <div className="flex items-center justify-between h-5">
                    <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest">Preview</h3>
                </div>

                <div className="bg-slate-50 border border-slate-200 rounded-2xl overflow-hidden min-h-[350px] flex flex-col">
                    {selectedTemplate ? (
                        <div className="flex-1 bg-white">
                            <div className="p-5 border-b border-slate-100 bg-slate-50/50 flex gap-2 text-xs">
                                <span className="font-bold text-slate-400 uppercase">Subject:</span>
                                <span className="font-medium text-slate-900">{selectedTemplate.subject || '(None)'}</span>
                            </div>
                            <div className="p-8">
                                <h4 className="text-lg font-bold text-slate-900 mb-4 underline decoration-indigo-200">Hi {"{{customer_name}}"},</h4>
                                <div className="text-sm text-slate-600 leading-relaxed mb-6">
                                    Thank you for shopping at <span className="text-indigo-600 font-bold">{"{{store_name}}"}</span>!
                                </div>
                                <div className="mt-8 p-10 bg-slate-50 border border-slate-100 rounded-2xl text-center">
                                    <FileText className="w-8 h-8 text-slate-200 mx-auto mb-3" />
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Layout logic</p>
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="flex-1 flex flex-col items-center justify-center p-12 text-center opacity-40">
                            <FileText className="w-10 h-10 text-slate-300 mb-3" />
                            <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Select a template</p>
                        </div>
                    )}
                </div>

                <div className="p-4 bg-white border border-slate-200 rounded-2xl flex flex-col sm:flex-row gap-3">
                    <div className="flex-1 relative">
                        <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                        <input
                            type="email"
                            value={testEmail}
                            onChange={(e) => setTestEmail(e.target.value)}
                            placeholder="Test email address"
                            className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-xl text-sm focus:border-indigo-500 outline-none"
                        />
                    </div>
                    <button
                        onClick={handleSendTest}
                        disabled={!selectedTemplate || !testEmail || sendingTest}
                        className="px-6 py-2 bg-slate-900 text-white rounded-xl text-xs font-black uppercase tracking-widest hover:bg-slate-800 disabled:opacity-30 transition-all flex items-center justify-center gap-2 font-black"
                    >
                        {sendingTest ? "Sending..." : "Send Test"}
                    </button>
                    {testFeedback && (
                        <span className={`text-[10px] font-bold px-3 py-2 rounded-lg ${testFeedback.type === 'success' ? 'bg-emerald-50 text-emerald-700' : 'bg-red-50 text-red-700'}`}>
                            {testFeedback.message}
                        </span>
                    )}
                </div>
            </div>
        </div>
    );
};

/** Step 4: Review & Compliance Gate */
const ReviewStep: React.FC<StepProps> = ({ data, onValidate }) => {
    const { data: eligibility, loading: audienceLoading } = useContacts();
    const { data: templates } = useTemplates();
    const [complianceChecked, setComplianceChecked] = useState(false);

    const selectedTemplate = templates.find((t: EmailTemplate) => t.id === data.templateId);

    // ── Compliance checks ──────────────────────────────────────────────
    const complianceChecks = useMemo(() => [
        {
            id: 'unsubscribe',
            label: 'Unsubscribe link present in template',
            passed: !!data.templateId, // Backend enforces this on template level
        },
        {
            id: 'sender',
            label: 'Sender identity configured',
            passed: !!(data.senderName && data.replyTo),
        },
        {
            id: 'consent',
            label: 'Consent verified for audience',
            passed: !!(eligibility && eligibility.eligible > 0),
        },
    ], [data.templateId, data.senderName, data.replyTo, eligibility]);

    const allChecksPassed = complianceChecks.every((c) => c.passed);
    const hasTemplate = !!data.templateId;
    const hasAudience = !!data.segmentId;
    const eligibleCount = eligibility?.eligible ?? 0;
    const excludedCount = eligibility?.excluded ?? 0;
    const isBlocked = !allChecksPassed || !hasTemplate || !hasAudience || eligibleCount === 0 || !complianceChecked;

    // ── Validate for wizard navigation ─────────────────────────────────
    React.useEffect(() => {
        onValidate?.(!isBlocked);
    }, [isBlocked, onValidate]);

    return (
        <div className="space-y-6">
            {/* ── 1. Campaign Summary ─────────────────────────────────── */}
            <div>
                <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                    <Mail className="w-3.5 h-3.5" /> Campaign Summary
                </h3>
                <div className="bg-slate-50 rounded-2xl border border-slate-200 divide-y divide-slate-100 overflow-hidden">
                    {[
                        { label: 'Name', value: data.name },
                        { label: 'Subject', value: data.subject },
                        { label: 'Sender', value: data.senderName ? `${data.senderName} <${data.replyTo}>` : '' },
                        { label: 'Schedule', value: data.scheduledAt || 'Send immediately' },
                    ].map((f) => (
                        <div key={f.label} className="flex px-5 py-3 text-sm">
                            <span className="w-28 text-[10px] font-black text-slate-400 uppercase tracking-widest pt-0.5">{f.label}</span>
                            <span className="font-semibold text-slate-900 flex-1">
                                {f.value || <span className="text-rose-400 text-xs italic">Missing</span>}
                            </span>
                        </div>
                    ))}
                </div>
            </div>

            {/* ── 2. Audience Summary ─────────────────────────────────── */}
            <div>
                <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                    <Users className="w-3.5 h-3.5" /> Audience Summary
                </h3>
                {audienceLoading ? (
                    <div className="h-20 bg-slate-50 border border-slate-100 rounded-2xl animate-pulse" />
                ) : eligibility ? (
                    <div className="grid grid-cols-3 gap-3">
                        <div className="p-4 bg-slate-50 border border-slate-200 rounded-2xl">
                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-0.5">Total</p>
                            <p className="text-xl font-black text-slate-900">{eligibility.total.toLocaleString()}</p>
                        </div>
                        <div className="p-4 bg-emerald-50 border border-emerald-200 rounded-2xl">
                            <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest mb-0.5">Eligible</p>
                            <p className="text-xl font-black text-emerald-700">{eligibility.eligible.toLocaleString()}</p>
                        </div>
                        <div className="p-4 bg-rose-50 border border-rose-200 rounded-2xl">
                            <p className="text-[10px] font-black text-rose-500 uppercase tracking-widest mb-0.5">Excluded</p>
                            <p className="text-xl font-black text-rose-700">{eligibility.excluded.toLocaleString()}</p>
                        </div>
                    </div>
                ) : (
                    <div className="p-4 bg-amber-50 border border-amber-200 rounded-xl text-xs font-medium text-amber-800">Audience data unavailable.</div>
                )}
            </div>

            {/* ── 3. Exclusion Breakdown ──────────────────────────────── */}
            {eligibility && excludedCount > 0 && (
                <div>
                    <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                        <Info className="w-3.5 h-3.5" /> Exclusion Breakdown
                    </h3>
                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                        {[
                            { label: 'No Consent', count: eligibility.reasons.noConsent },
                            { label: 'Unsubscribed', count: eligibility.reasons.unsubscribed },
                            { label: 'Suppressed', count: eligibility.reasons.suppressed },
                            { label: 'Invalid Email', count: eligibility.reasons.invalid },
                        ].map((r) => (
                            <div key={r.label} className="px-3 py-2.5 bg-white border border-slate-100 rounded-xl flex items-center justify-between">
                                <span className="text-[10px] font-bold text-slate-500 uppercase">{r.label}</span>
                                <span className="text-sm font-black text-slate-900">{r.count.toLocaleString()}</span>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* ── 4. Template Preview ─────────────────────────────────── */}
            <div>
                <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                    <FileText className="w-3.5 h-3.5" /> Template
                </h3>
                {selectedTemplate ? (
                    <div className="bg-white border border-slate-200 rounded-2xl overflow-hidden">
                        <div className="px-5 py-3 border-b border-slate-100 bg-slate-50/50 flex items-center justify-between">
                            <span className="text-sm font-bold text-slate-900">{selectedTemplate.name}</span>
                            <span className="text-[10px] px-2 py-0.5 bg-emerald-50 text-emerald-700 font-bold rounded-full">Selected</span>
                        </div>
                        <div className="p-6 text-sm text-slate-600">
                            <p><span className="font-bold text-slate-900">Subject:</span> {selectedTemplate.subject || '(None)'}</p>
                            <div className="mt-4 p-6 bg-slate-50 border border-slate-100 rounded-xl text-center">
                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Template content preview</p>
                            </div>
                        </div>
                    </div>
                ) : (
                    <div className="p-4 bg-rose-50 border border-rose-200 rounded-xl flex items-center gap-2">
                        <XCircle className="w-4 h-4 text-rose-500" />
                        <span className="text-xs font-bold text-rose-700">No template selected — campaign cannot be sent.</span>
                    </div>
                )}
            </div>

            {/* ── 5. Compliance Validation ────────────────────────────── */}
            <div>
                <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                    <ShieldCheck className="w-3.5 h-3.5" /> Compliance Checks
                </h3>
                <div className="bg-white border border-slate-200 rounded-2xl divide-y divide-slate-100 overflow-hidden">
                    {complianceChecks.map((check) => (
                        <div key={check.id} className="flex items-center gap-3 px-5 py-3.5">
                            {check.passed ? (
                                <CheckCircle2 className="w-5 h-5 text-emerald-500 shrink-0" />
                            ) : (
                                <XCircle className="w-5 h-5 text-rose-500 shrink-0" />
                            )}
                            <span className={`text-sm font-medium ${check.passed ? 'text-slate-700' : 'text-rose-700'}`}>
                                {check.label}
                            </span>
                            <span className={`ml-auto text-[10px] font-black uppercase tracking-widest px-2 py-0.5 rounded-full
                                ${check.passed ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                                {check.passed ? 'Passed' : 'Failed'}
                            </span>
                        </div>
                    ))}
                </div>
                {!allChecksPassed && (
                    <div className="mt-3 p-4 bg-rose-50 border border-rose-200 rounded-xl flex items-start gap-3">
                        <XCircle className="w-5 h-5 text-rose-500 shrink-0 mt-0.5" />
                        <div>
                            <p className="text-sm font-bold text-rose-900">Compliance requirements not met</p>
                            <p className="text-xs text-rose-700 mt-0.5">All compliance checks must pass before this campaign can be sent.</p>
                        </div>
                    </div>
                )}
            </div>

            {/* ── 6. Warning Section ──────────────────────────────────── */}
            {eligibility && eligibleCount === 0 && (
                <div className="p-4 bg-rose-50 border-2 border-rose-300 rounded-xl flex items-start gap-3 ring-2 ring-rose-100">
                    <XCircle className="w-5 h-5 text-rose-600 shrink-0 mt-0.5" />
                    <div>
                        <p className="text-sm font-black text-rose-900">Campaign Blocked</p>
                        <p className="text-xs text-rose-700 mt-0.5">There are zero eligible contacts. This campaign cannot proceed.</p>
                    </div>
                </div>
            )}
            {excludedCount > 0 && eligibleCount > 0 && (
                <div className="p-4 bg-amber-50 border border-amber-200 rounded-xl flex items-start gap-3">
                    <TriangleAlert className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" />
                    <div>
                        <p className="text-sm font-bold text-amber-900">
                            {excludedCount.toLocaleString()} contact{excludedCount !== 1 ? 's' : ''} will be excluded
                        </p>
                        <p className="text-xs text-amber-700 mt-0.5">These contacts were removed due to compliance rules (unsubscribed, no consent, suppressed, or invalid).</p>
                    </div>
                </div>
            )}

            {/* ── 7. Mandatory Confirmation ───────────────────────────── */}
            <div className={`p-5 rounded-2xl border-2 transition-all duration-300
                ${complianceChecked
                    ? 'bg-emerald-50 border-emerald-300 ring-1 ring-emerald-200'
                    : 'bg-slate-50 border-slate-200'}`}>
                <label className="flex items-start gap-3 cursor-pointer select-none">
                    <input
                        type="checkbox"
                        checked={complianceChecked}
                        onChange={(e) => setComplianceChecked(e.target.checked)}
                        className="w-5 h-5 rounded border-slate-300 text-indigo-600 focus:ring-indigo-500 mt-0.5 cursor-pointer accent-indigo-600"
                    />
                    <div>
                        <p className={`text-sm font-bold ${complianceChecked ? 'text-emerald-900' : 'text-slate-700'}`}>
                            I confirm this campaign complies with email regulations
                        </p>
                        <p className="text-[11px] text-slate-500 mt-0.5">
                            Including CAN-SPAM, GDPR, and other applicable anti-spam laws. This campaign only targets contacts who have given explicit consent.
                        </p>
                    </div>
                </label>
            </div>
        </div>
    );
};

/** Step 5: Send */
const SendStep: React.FC<StepProps> = ({ data, onChange }) => (
    <div className="space-y-6">
        <div className="p-6 bg-indigo-50 border border-indigo-100 rounded-2xl">
            <h3 className="text-sm font-bold text-indigo-900 mb-1">Finalize Campaign</h3>
            <p className="text-xs text-indigo-600">Schedule your campaign or send it immediately.</p>
        </div>
        <div>
            <label className="block text-xs font-bold text-slate-600 uppercase tracking-wider mb-2">Schedule (optional)</label>
            <input
                type="datetime-local"
                value={data.scheduledAt || ''}
                onChange={(e) => onChange({ scheduledAt: e.target.value || undefined })}
                className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:border-indigo-500 outline-none"
            />
        </div>
    </div>
);

// ============================================================================
// WIZARD
// ============================================================================

export const CreateCampaignPage: React.FC = () => {
    const router = useRouter();
    const [currentStep, setCurrentStep] = useState(0);
    const [campaignData, setCampaignData] = useState<CreateCampaignPayload>(INITIAL_DATA);
    const [isStepValid, setIsStepValid] = useState(true);

    const step = STEPS[currentStep];
    const isFirst = currentStep === 0;
    const isLast = currentStep === STEPS.length - 1;

    const handleDataChange = (updates: Partial<CreateCampaignPayload>) => {
        setCampaignData((prev) => ({ ...prev, ...updates }));
    };

    const handleNext = () => {
        if (!isLast && isStepValid) {
            setCurrentStep((s) => s + 1);
            setIsStepValid(true);
        }
    };

    const handleBack = () => {
        if (!isFirst) {
            setCurrentStep((s) => s - 1);
            setIsStepValid(true);
        }
    };

    const handleSubmit = () => {
        console.log('[CreateCampaign] Submit:', campaignData);
    };

    const STEP_COMPONENTS: Record<StepId, React.FC<StepProps>> = {
        basics: BasicsStep,
        audience: AudienceStep,
        content: ContentStep,
        review: ReviewStep,
        send: SendStep,
    };

    const ActiveStepComponent = step ? STEP_COMPONENTS[step.id] : null;

    return (
        <div className="max-w-[950px] mx-auto space-y-6 pb-20 px-2 lg:px-4">
            <div className="flex items-center gap-3 border-b border-slate-100 pb-6 pt-2">
                <button onClick={() => router.push('/backoffice/email-campaigns')} className="p-2 hover:bg-slate-100 rounded-xl transition-colors mr-2">
                    <ArrowLeft size={20} className="text-slate-600" />
                </button>
                <div className="p-2.5 bg-indigo-600 rounded-xl shadow-lg shadow-indigo-100">
                    <Mail className="w-5 h-5 text-white" />
                </div>
                <div className="flex-1">
                    <h1 className="text-2xl font-black text-slate-900 tracking-tight">Create Campaign</h1>
                    <p className="text-[11px] font-bold text-slate-400 uppercase tracking-[0.2em] mt-0.5">Step {currentStep + 1} of {STEPS.length} — {step?.label}</p>
                </div>
            </div>

            <nav className="flex items-center gap-1">
                {STEPS.map((s, idx) => (
                    <React.Fragment key={s.id}>
                        <button
                            onClick={() => idx <= currentStep && (idx === 0 || isStepValid) && setCurrentStep(idx)}
                            disabled={idx > currentStep}
                            className={`flex items-center gap-2 px-3.5 py-2 rounded-xl text-xs font-bold transition-all
                                ${idx === currentStep ? 'bg-indigo-600 text-white shadow-md shadow-indigo-200' : 
                                  idx < currentStep ? 'bg-indigo-50 text-indigo-700 hover:bg-indigo-100' : 'bg-slate-50 text-slate-400 cursor-not-allowed'}`}
                        >
                            {idx < currentStep ? <Check className="w-3.5 h-3.5" /> : <s.icon className="w-3.5 h-3.5" />}
                            <span className="hidden sm:inline">{s.label}</span>
                        </button>
                        {idx < STEPS.length - 1 && <div className={`flex-1 h-px max-w-8 ${idx < currentStep ? 'bg-indigo-300' : 'bg-slate-200'}`} />}
                    </React.Fragment>
                ))}
            </nav>

            <section className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden min-h-[450px]">
                <div className="px-6 py-4 border-b border-slate-100 bg-slate-50/50">
                    <h2 className="text-base font-bold text-slate-800">{step?.label}</h2>
                    <p className="text-xs text-slate-400 mt-0.5">
                        {step?.id === 'basics' && 'Configure campaign details.'}
                        {step?.id === 'audience' && 'Verify audience compliance.'}
                        {step?.id === 'content' && 'Select template and preview content.'}
                        {step?.id === 'review' && 'Verify compliance before sending.'}
                        {step?.id === 'send' && 'Choose when to launch.'}
                    </p>
                </div>
                <div className="p-6">
                    {ActiveStepComponent && (
                        <ActiveStepComponent 
                            data={campaignData} 
                            onChange={handleDataChange} 
                            onValidate={(v) => setIsStepValid(v)}
                        />
                    )}
                </div>
            </section>

            <div className="flex items-center justify-between">
                <button onClick={handleBack} disabled={isFirst} className="flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-bold transition-all text-slate-600 bg-white border border-slate-200 hover:bg-slate-50 disabled:opacity-30">
                    <ArrowLeft className="w-4 h-4" /> Back
                </button>
                {isLast ? (
                    <button onClick={handleSubmit} className="flex items-center gap-2 px-6 py-2.5 bg-indigo-600 text-white rounded-xl text-sm font-black uppercase tracking-widest shadow-lg shadow-indigo-200 hover:bg-indigo-700 active:scale-95 transition-all">
                        <Send className="w-4 h-4" /> {campaignData.scheduledAt ? 'Schedule' : 'Send Now'}
                    </button>
                ) : (
                    <button onClick={handleNext} disabled={!isStepValid} className="flex items-center gap-2 px-6 py-2.5 bg-indigo-600 text-white rounded-xl text-sm font-bold shadow-lg shadow-indigo-200 hover:bg-indigo-700 disabled:bg-slate-300 disabled:shadow-none transition-all active:scale-95">
                        Next <ArrowRight className="w-4 h-4" />
                    </button>
                )}
            </div>
        </div>
    );
};

export default CreateCampaignPage;
